#!/usr/bin/env node
/**
 * Blog-index link resolvability gate.
 *
 * WHY THIS EXISTS (2026-07-28)
 *
 * /blog/index.html is generated by scripts/build-blog-index.mjs from
 * data/library-tags.json#blog_posts, and it emits `/blog/<slug>/` for EVERY
 * entry — the builder does not read the `namespace` field. That is fine,
 * because the Phase-7 split (May 2026) moved evergreen articles to /library/
 * and left a 301 map behind: src/lib/blog-library-redirects.js, which lives in
 * code rather than _redirects because Cloudflare caps a project at 100
 * _redirects rules.
 *
 * So a blog-index link is correct if EITHER the post really exists at
 * blog/<slug>/, OR the redirect map carries '/blog/<slug>/'. Add a
 * library-namespace entry to blog_posts without adding the matching 301 and
 * the index ships a link to nothing.
 *
 * That has now happened three times. The map's own comments record the first
 * two ("EN kept-slug gap-close (2026-07-18): two more library articles the
 * blog index still links at /blog/<slug>/ with no matching 301, found by a
 * redirect-worker-aware broken-link sweep"), and the third was
 * restaurant-prime-cost, found the same way on 2026-07-28. Three manual
 * discoveries of one mechanical invariant is the definition of something that
 * should be a gate rather than a habit.
 *
 * THE INVARIANT: every `/blog/<slug>/` href on a blog index resolves — to a
 * real post directory, or through the redirect map. Checked for EN and ES.
 *
 * Usage:
 *   node scripts/check-blog-index-links.mjs
 *   node scripts/check-blog-index-links.mjs --self-test
 *
 * Exit codes:
 *   0 — every link resolves.
 *   1 — at least one link resolves to nothing.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const REPO = path.resolve(path.dirname(__filename), '..');

const REDIRECT_MAP = 'src/lib/blog-library-redirects.js';
const INDEXES = [
  { file: 'blog/index.html', prefix: '/blog/', postDir: 'blog' },
  { file: 'es/blog/index.html', prefix: '/es/blog/', postDir: 'es/blog' },
];

/** Pull every same-namespace post link out of an index page. */
export function extractLinks(html, prefix) {
  const re = new RegExp(`href="(${prefix.replace(/\//g, '\\/')}[a-z0-9-]+\\/)"`, 'g');
  return [...new Set([...html.matchAll(re)].map((m) => m[1]))];
}

/**
 * A link resolves if the post directory exists, or the redirect map carries the
 * exact quoted path. The map is matched as a literal `'<path>'` so a substring
 * of a longer slug can never satisfy a shorter one.
 */
export function resolves(href, { prefix, postDir }, mapSource, exists) {
  const slug = href.slice(prefix.length).replace(/\/$/, '');
  if (exists(`${postDir}/${slug}/index.html`)) return true;
  return mapSource.includes(`'${href}'`);
}

function selfTest() {
  const map = "  ['/blog/moved/', '/library/moved/'],\n  ['/blog/moved-longer/', '/library/moved-longer/'],";
  const cfg = { prefix: '/blog/', postDir: 'blog' };
  const exists = (p) => p === 'blog/real/index.html';
  const cases = [
    [resolves('/blog/real/', cfg, map, exists), true, 'a real post directory resolves'],
    [resolves('/blog/moved/', cfg, map, exists), true, 'a redirected slug resolves'],
    [resolves('/blog/ghost/', cfg, map, exists), false, 'an unknown slug does not resolve'],
    [resolves('/blog/move/', cfg, map, exists), false, 'a prefix of a mapped slug must NOT resolve'],
    [extractLinks('<a href="/blog/a/">x</a><a href="/blog/a/">y</a>', '/blog/').length, 1, 'links de-duplicate'],
    [extractLinks('<a href="/library/a/">x</a>', '/blog/').length, 0, 'other namespaces are ignored'],
  ];
  let pass = 0;
  for (const [got, want, why] of cases) {
    if (got !== want) {
      console.error(`✗ self-test: ${why} — expected ${want}, got ${got}`);
      process.exit(2);
    }
    pass++;
  }
  console.log(`check-blog-index-links --self-test: OK (${pass} assertions)`);
  process.exit(0);
}

function main(argv) {
  if (argv.includes('--self-test')) selfTest();

  const mapPath = path.join(REPO, REDIRECT_MAP);
  if (!fs.existsSync(mapPath)) {
    console.error(`check-blog-index-links: FAIL — ${REDIRECT_MAP} is missing; every moved link would 404.`);
    process.exit(1);
  }
  const mapSource = fs.readFileSync(mapPath, 'utf8');
  const exists = (rel) => fs.existsSync(path.join(REPO, rel));

  const broken = [];
  let checked = 0;
  for (const cfg of INDEXES) {
    const abs = path.join(REPO, cfg.file);
    if (!fs.existsSync(abs)) continue;
    const links = extractLinks(fs.readFileSync(abs, 'utf8'), cfg.prefix);
    checked += links.length;
    for (const href of links) {
      if (!resolves(href, cfg, mapSource, exists)) broken.push({ file: cfg.file, href });
    }
  }

  if (!broken.length) {
    console.log(`check-blog-index-links: ${checked} index link(s) all resolve (post on disk or 301 in the map). 0 violations.`);
    process.exit(0);
  }

  console.error(`check-blog-index-links: ${broken.length} of ${checked} index link(s) resolve to nothing:\n`);
  for (const b of broken) console.error(`  ✗ ${b.file} → ${b.href}`);
  console.error(`
Cause is almost always a library-namespace entry added to
data/library-tags.json#blog_posts without the matching 301. The builder emits
/blog/<slug>/ for every entry regardless of namespace, so the two must land in
the same commit. Fix by adding to ${REDIRECT_MAP}:

  ['/blog/<slug>/',   '/library/<slug>/'],`);
  process.exit(1);
}

// Import-safe: only run the CLI when invoked directly.
if (import.meta.url === pathToFileURL(process.argv[1] || '').href) {
  main(process.argv.slice(2));
}
